<?php
declare(strict_types=1);
if(getenv('GITHUB_ACTIONS')!=='true'||getenv('SOKNA_R225_DISPOSABLE_ONLY')!=='YES')throw new RuntimeException('DISPOSABLE_ONLY');
$web=realpath((string)getenv('SOKNA_R213_WEB'));$tmp=realpath((string)getenv('RUNNER_TEMP'));
if(!$web||!$tmp||!str_starts_with($web,$tmp.DIRECTORY_SEPARATOR))throw new RuntimeException('NON_TEMP_REFUSED');
require_once $web.'/bootstrap.php';$cfg=require dirname($web).'/config.php';$core=sokna_local_bootstrap($cfg);$pdo=$core->database();$pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);
$fixture=json_decode((string)file_get_contents($tmp.'/r225-fixture.json'),true,512,JSON_THROW_ON_ERROR);
$sent=json_decode((string)file_get_contents($tmp.'/r225-submission.json'),true,512,JSON_THROW_ON_ERROR);
$q=$pdo->prepare('SELECT o.id,o.status,o.total_amount,oi.id order_item_id,oi.quantity,oi.unit_price FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.public_code=? AND o.client_token=?');
$q->execute([$sent['order_code'],$sent['client_token']]);$order=$q->fetch();
$checks=0;
$ok=static function(bool $condition,string $label)use(&$checks):void{if(!$condition)throw new RuntimeException('FAIL_R225_'.$label);$checks++;echo 'PASS_R225_'.$label."\n";};
$ok(is_array($order)&&$order['status']==='pending_approval','REAL_DB_STILL_PENDING_AFTER_HTTP');
$ok((int)$order['quantity']===2&&(int)$order['unit_price']===37000&&(int)$order['total_amount']===74000,'REAL_DB_PARENT_PRICE_QUANTITY');
$oi=(int)$order['order_item_id'];$orderId=(int)$order['id'];
$components=$pdo->prepare('SELECT component_item_id,quantity,component_mode FROM order_item_bundle_components WHERE order_item_id=? ORDER BY id');$components->execute([$oi]);$list=$components->fetchAll();
$ok(count($list)===2 && array_map('intval',array_column($list,'quantity'))===[4,2],'REAL_DB_FROZEN_FIXED_AND_CHOICE_COMPONENTS');
$balance=(int)$pdo->query('SELECT quantity_base FROM inventory_balances WHERE inventory_item_id='.(int)$fixture['inventory'])->fetchColumn();
$ok($balance===100000,'NO_STOCK_DEBIT_BEFORE_APPROVAL');
$admin=['id'=>(int)$fixture['admin_id'],'role'=>'admin'];
$r=$core->orderStaffActions()->changeStatus(['order_id'=>$orderId,'status'=>'accounted'],$admin);
$ok(($r['status']??'')==='accounted'&&empty($r['idempotent']),'STAFF_APPROVAL_AFTER_HTTP');
$replayed=$core->orderStaffActions()->changeStatus(['order_id'=>$orderId,'status'=>'accounted'],$admin);
$ok(($replayed['idempotent']??false)===true,'STAFF_APPROVAL_RETRY_IDEMPOTENT');
$event=$pdo->query("SELECT id,status FROM inventory_order_events WHERE order_id=$orderId AND event_type='accounted' ORDER BY id")->fetchAll();
$ok(count($event)===1&&$event[0]['status']==='done','ONE_ACCOUNTED_EVENT_DONE');
$mov=$pdo->prepare("SELECT quantity_base,total_cost_delta FROM inventory_movements WHERE source_type='order_item' AND source_id=? ORDER BY id");$mov->execute([$oi]);$moves=$mov->fetchAll();
$ok(count($moves)===2&&array_map('intval',array_column($moves,'quantity_base'))===[-40,-8],'TWO_CHILD_MOVEMENTS_NOT_PARENT');
$end=(int)$pdo->query('SELECT quantity_base FROM inventory_balances WHERE inventory_item_id='.(int)$fixture['inventory'])->fetchColumn();
$ok($end===99952,'FINAL_STOCK_DEBIT_EXACTLY_ONCE');
$ok(array_sum(array_map('intval',array_column($moves,'total_cost_delta')))===-144,'HISTORICAL_MATERIAL_COST_144');
$pdo->prepare('UPDATE inventory_balances SET average_unit_cost=9.000000 WHERE inventory_item_id=?')->execute([(int)$fixture['inventory']]);
$original=$pdo->prepare("SELECT total_cost_delta FROM inventory_movements WHERE source_type='order_item' AND source_id=? ORDER BY id");$original->execute([$oi]);
$ok(array_sum(array_map('intval',$original->fetchAll(PDO::FETCH_COLUMN)))===-144,'CHANGED_PURCHASE_AVERAGE_DOES_NOT_REPRICE_ORDER');
$pdo->beginTransaction();$again=$core->inventoryOrders()->enqueueAccountedTx($orderId,(int)$fixture['admin_id']);$pdo->commit();
$ok((int)$again===(int)$event[0]['id']&&$end===(int)$pdo->query('SELECT quantity_base FROM inventory_balances WHERE inventory_item_id='.(int)$fixture['inventory'])->fetchColumn(),'INVENTORY_ACCOUNTED_RETRY_EXACTLY_ONCE');
echo 'PASS_R225_REAL_HTTP_TO_ACCOUNTED_INVENTORY_'.$checks."_CHECKS\n";